class Solution:
    def minimumAnagramLength(self, s: str) -> int:
        n = len(s)
        for l in range(1, n + 1):
            if n % l:
                continue
            base = [0] * 26
            for ch in s[:l]:
                base[ord(ch) - 97] += 1
            ok = True
            for st in range(l, n, l):
                cur = [0] * 26
                for ch in s[st:st + l]:
                    cur[ord(ch) - 97] += 1
                if cur != base:
                    ok = False
                    break
            if ok:
                return l
        return n

