class Solution {
    public int minimumAnagramLength(String s) {
        int n = s.length();
        for (int l = 1; l <= n; l++) {
            if (n % l != 0) continue;
            int[] base = new int[26];
            for (int i = 0; i < l; i++) base[s.charAt(i) - 'a']++;
            boolean ok = true;
            for (int st = l; st < n && ok; st += l) {
                int[] cur = new int[26];
                for (int i = st; i < st + l; i++) cur[s.charAt(i) - 'a']++;
                if (!java.util.Arrays.equals(cur, base)) ok = false;
            }
            if (ok) return l;
        }
        return n;
    }
}

