class Solution:
    def minimumAnagramLength(self, s: str) -> int:
        import random
        n = len(s)
        w = [random.randrange(1, 1 << 61) for _ in range(26)]
        MOD = (1 << 61) - 1
        sig = [0] * (n + 1)
        for i, ch in enumerate(s):
            sig[i + 1] = (sig[i] + w[ord(ch) - 97]) % MOD
        for l in range(1, n + 1):
            if n % l:
                continue
            target = (sig[l] - sig[0]) % MOD
            if all((sig[st + l] - sig[st]) % MOD == target for st in range(l, n, l)):
                return l
        return n

