class Solution {
public:
    int minimumAnagramLength(string s) {
        int n = s.size();
        const unsigned long long MOD = (1ULL << 61) - 1;
        vector<unsigned long long> w(26);
        mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());
        for (auto& x : w) x = rng() % MOD;
        vector<unsigned long long> sig(n + 1, 0);
        for (int i = 0; i < n; i++)
            sig[i + 1] = (sig[i] + w[s[i] - 'a']) % MOD;
        auto sub = [&](int a, int b) { return (sig[b] + MOD - sig[a]) % MOD; };
        for (int l = 1; l <= n; l++) {
            if (n % l) continue;
            unsigned long long t = sub(0, l);
            bool ok = true;
            for (int st = l; st < n; st += l)
                if (sub(st, st + l) != t) { ok = false; break; }
            if (ok) return l;
        }
        return n;
    }
};

