class Solution {
    public int minimumAnagramLength(String s) {
        int n = s.length();
        long MOD = (1L << 61) - 1;
        long[] w = new long[26];
        java.util.Random rnd = new java.util.Random();
        for (int i = 0; i < 26; i++) w[i] = rnd.nextLong(MOD - 1) + 1;
        long[] sig = new long[n + 1];
        for (int i = 0; i < n; i++)
            sig[i + 1] = (sig[i] + w[s.charAt(i) - 'a']) % MOD;
        for (int l = 1; l <= n; l++) {
            if (n % l != 0) continue;
            long t = sig[l];
            boolean ok = true;
            for (int st = l; st < n; st += l) {
                long cur = (sig[st + l] - sig[st] + MOD) % MOD;
                if (cur != t) { ok = false; break; }
            }
            if (ok) return l;
        }
        return n;
    }
}

